insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('c9b18ab8-1825-4a94-98e3-277bc27d94ca', '80c5b769-0dba-40cd-8340-638f2057435f', $$inleiding en figuur 1 — AFP-eiwitten (mechanisme 1)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-chillen-bij-60-c-context1.png$$,
   $$Sommige kevers, zoals de Upis ceramboides, kunnen in poolgebieden een temperatuur van −60 °C overleven. Dat hebben ze onder andere te danken aan twee mechanismen die bevriezing van het water in hun lichaam voorkomen. Mechanisme 1: ijs-bindende eiwitten. Sommige poolkevers maken speciale eiwitten (AFP's) aan. De AFP-moleculen binden met waterstofbruggen aan kleine ijskristallen en voorkomen zo het uitgroeien tot grotere ijskristallen die cellen en/of organen zouden beschadigen. Een goed gekarakteriseerde AFP van een kever is TmAFP (zie figuur 1). AFP's van andere kevers lijken hierop: karakteristiek zijn de windingen van telkens 12 aminozuren. De aminozuurvolgorde van iedere winding kan worden weergegeven met de codering TCTxSxxCxxAx. In deze codering wordt elk aminozuur weergegeven met één letter (zie Binas-tabel 67H) en is een x gebruikt voor een willekeurig aminozuur. Figuur 1: schematische weergave van een gedeelte van TmAFP, met per winding telkens een herhaling van de aminozuren T-C-T, verbonden door een stippellijn (waterstofbrug) tussen opeenvolgende windingen.$$, 'inline'),
  ('4bfd3c1c-9112-46fb-a60e-b4dc2047677f', '80c5b769-0dba-40cd-8340-638f2057435f', $$vorming van zwavelbruggen tussen SH-groepen (redoxreactie)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-chillen-bij-60-c-context2.png$$,
   $$In de zich vormende AFP worden tussen de SH groepen van opeenvolgende cysteïne-eenheden covalente bindingen gevormd, de zogeheten zwavelbruggen. Deze reactie is een redoxreactie, die onvolledig is weergegeven: twee losse ~T-C-T~ ketens met elk een SH-groep aan een cysteïne-eenheid reageren tot een keten waarin de twee cysteïne-eenheden met elkaar verbonden zijn via een S–S-brug, onder afsplitsing van 2 H⁺.$$, 'inline'),
  ('26ea88ae-2617-4697-a969-b2eec69769b7', '80c5b769-0dba-40cd-8340-638f2057435f', $$uitwerkbijlage vraag 3 — structuurformule van de polysacharide (Man-Xyl, n = 20)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-chillen-bij-60-c-context3.png$$,
   $$Op de uitwerkbijlage is de structuurformule van de polysacharide weergegeven: een herhalende eenheid van een mannose-eenheid (met een CH₂OH-zijgroep) gekoppeld via een zuurstofbrug aan een xylose-eenheid, met aan beide uiteinden van de keten een H–O-groep en een herhaling van 20 eenheden (aangeduid met het getal 20 onderaan de haakjes), gevolgd door een plusteken en een pijl voor de te voltooien reactievergelijking.$$, 'uitwerkbijlage'),
  ('8233bde3-8d51-422f-ad36-80eb7ac77694', '80c5b769-0dba-40cd-8340-638f2057435f', $$hypothese: antivriesstof verankerd via vetzuurstaarten in het celmembraan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-chillen-bij-60-c-context4.png$$,
   $$In de oplossing die ontstond na de hydrolyse waren ook vrije vetzuren aanwezig. Een onderzoeker vermoedde dat moleculen van de polysacharide veresterd zijn met één of meerdere moleculen van de vetzuren. Hij stelde de volgende hypothese op: "Moleculen van de antivriesstof bevinden zich in de vloeistof buiten de cel. Deze moleculen zijn verankerd in het celmembraan door de staarten van één of meerdere vetzuren." Op de uitwerkbijlage staat een celmembraan schematisch weergegeven.$$, 'inline'),
  ('1e633a14-075e-4500-9d85-638f5508c75e', '80c5b769-0dba-40cd-8340-638f2057435f', $$uitwerkbijlage vraag 4 — doorsnede celmembraan$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-chillen-bij-60-c-context5.png$$,
   $$Op de uitwerkbijlage is een doorsnede van een celmembraan schematisch weergegeven: twee lagen van elk elf moleculen met een bolvormige kop (gericht naar de vloeistof buiten de cel, respectievelijk naar de vloeistof binnen de cel) en een golvende staart naar het midden van de doorsnede, met de aanduiding 'doorsnede celmembraan' tussen de twee lagen.$$, 'uitwerkbijlage'),
  ('b439a21f-f24f-41dc-8fb0-3bddd15651e0', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', $$inleiding — energiedichtheid van waterstof bij 700 bar versus benzine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-waterstof-brandstofcel-context1.png$$,
   $$In het eerste waterstof-tankstation van Nederland wordt waterstofgas bij een druk van 700 bar overgepompt in de tank van de auto. De druk wordt zo hoog gehouden omdat de energiedichtheid van de waterstof dan veel hoger is dan wanneer waterstof bij gewone druk zou worden gebruikt. De energiedichtheid van benzine bij volledige verbranding bedraagt 46 MJ kg⁻¹, wat overeenkomt met 3,3·10⁴ MJ m⁻³. Het ontstane water komt hierbij vrij als gas. De energiedichtheid van waterstof bij 700 bar is hoger dan die van benzine wanneer deze wordt uitgedrukt in MJ kg⁻¹, maar lager wanneer deze wordt uitgedrukt in MJ m⁻³.$$, 'inline'),
  ('0eba0988-01bc-4ab6-bd5a-37bb54475747', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', $$elektrolyse- en brandstofcelrendement$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-waterstof-brandstofcel-context2.png$$,
   $$Als de waterstof door elektrolyse van water wordt bereid, gaat 35% van de toegevoerde elektrische energie verloren. Het energie-rendement van een waterstof-brandstofcel bedraagt gemiddeld 45%. In beide gevallen is het verlies aan energie vooral te wijten aan de ontwikkeling van warmte. Overige rendementsverliezen worden hierbij verwaarloosd. Het totale energie-rendement van de vorming van waterstof uit water, waarna het in een brandstofcel wordt gebruikt, is hierdoor laag.$$, 'inline'),
  ('597eabfa-7eb0-4f17-9d48-23607b721412', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', $$membraanmateriaal Nafion-117 en figuur 1 (structuurformule)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-waterstof-brandstofcel-context3.png$$,
   $$Veel onderzoek richt zich op het membraan dat tussen de elektrodes aanwezig is. Het meest gebruikte membraanmateriaal is Nafion-117. Een molecuul van Nafion is opgebouwd uit twee monomeren. Figuur 1 toont een gedeelte uit een molecuul Nafion: een keten van herhaalde eenheden (–CF–CF₂–)(–CF₂–CF₂–)n met daaraan een zijketen –O–CF₂–CF(CF₃)–O–CF₂–CF₂–OSO₃H. Omdat de waarde van n kan variëren, bestaan verschillende typen Nafion. De aanduiding 117 geeft daarom informatie over de structuur van het membraan. De eerste twee cijfers geven aan dat per 1100 gram materiaal één mol sulfonzuurgroepen (~OSO₃H) voorkomt. Het cijfer 7 geeft informatie over de dikte van het membraan.$$, 'inline'),
  ('d45499e4-ec48-4d4b-9dae-8196aa7cbff8', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', $$Nafion neemt water op; zure werking van de sulfonzuurgroep$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-waterstof-brandstofcel-context4.png$$,
   $$Als Nafion in contact wordt gebracht met water zwelt het materiaal op door opname van water. Door het sterk hydrofiele karakter van de zijketens vormen zich holtes en kanalen in het materiaal. In deze holtes is water aanwezig. De sulfonzuurgroepen die aan het eind van de zijketens van het polymeer aanwezig zijn, steken in de holtes. Deze groepen gedragen zich in water als sterk zuur, waardoor in de holtes H⁺ ionen aanwezig zijn. Het zure karakter van de sulfonzuurgroep wordt onder andere veroorzaakt doordat van de geconjugeerde R–OSO₃⁻ groep meerdere grensstructuren mogelijk zijn.$$, 'inline'),
  ('425d6a79-ee14-48f1-b884-50db3952d154', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', $$protontransport door het membraan en halfreacties van de brandstofcel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-waterstof-brandstofcel-context5.png$$,
   $$Tijdens stroomlevering bewegen gehydrateerde H⁺ ionen door het materiaal heen. Door de reacties die in de brandstofcel optreden en de beweging van gehydrateerde H⁺ ionen wordt het watergehalte in het membraan beïnvloed. Voor een optimale werking moet het gehalte water in het membraan constant blijven. De halfreacties aan de elektrodes in een waterstof-brandstofcel zijn hieronder weergegeven: H₂ → 2 H⁺ + 2 e⁻ (negatieve elektrode); O₂ + 4 H⁺ + 4 e⁻ → 2 H₂O (positieve elektrode). De H⁺ ionen die aan de negatieve elektrode gevormd zijn, bewegen door het membraan naar de andere elektrode. Uit onderzoek blijkt dat elk H⁺ ion gemiddeld 2,7 moleculen water meesleept van de ene kant van het membraan naar de andere kant. Om het watergehalte in het membraan constant te houden moet dus aan de elektrodes water worden aangevoerd dan wel worden afgevoerd.$$, 'inline'),
  ('adcfafab-900e-430f-9846-7e086a4c1ead', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$inleiding en figuur 1 — netwerkstructuur via waterstofbruggen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context1.png$$,
   $$Een groep onderzoekers heeft een elastisch materiaal ontwikkeld met zelfherstellende eigenschappen. Als een elastiekje van dit materiaal wordt doorgesneden, hechten de twee delen bij samendrukken weer aan elkaar. Na afloop is het elastiekje weer net zo sterk en elastisch. Het materiaal bestaat uit allerlei verschillende moleculen, die elk zijn opgebouwd uit een aantal dezelfde basiseenheden. Figuur 1 toont schematisch de microstructuur van dit materiaal: een netwerk van basiseenheden waarbij één molecuul (omcirkeld) uit een aantal eenheden bestaat, met stippellijnen tussen de verschillende moleculen. De stippellijnen geven waterstofbruggen weer tussen de verschillende moleculen. Door de vele waterstofbruggen vormen de moleculen een stevige netwerkstructuur, waardoor het materiaal elastische eigenschappen krijgt.$$, 'inline'),
  ('a546744b-4dcd-4cb3-b59e-da73afb2f765', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$vorming van het dizuur door een additiereactie (stap 1)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context2.png$$,
   $$De vorming van het materiaal kan in drie stappen worden weergegeven. Stap 1: door een additiereactie van twee moleculen van een meervoudig onverzadigd vetzuur wordt een dizuur gevormd. Het mechanisme van deze additiereactie is vereenvoudigd weergegeven: twee moleculen met elk twee onverzadigde bindingen reageren tot een zesring met één overgebleven dubbele binding. De structuurformule van het dizuur dat volgens deze additiereactie is gevormd, is hieronder weergegeven: een zesring met een dubbele binding, waaraan enerzijds een keten –(CH₂)₇–C(=O)OH en een keten –(CH₂)₅–CH₃ zijn gebonden, en anderzijds een HC=CH-zijketen die verder verbonden is met CH₃–(CH₂)₅– en met een tweede keten –(CH₂)₇–C(=O)OH.$$, 'inline'),
  ('f32fdeb3-5beb-4e22-a877-78813bceea9f', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$reactie van het dizuur met diëthyleentriamine (DET) (stap 2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context3.png$$,
   $$Stap 2: men laat het dizuur reageren met diëthyleentriamine (DET) om aan het gevormde dizuur waterstofbrugvormende groepen aan te brengen. De structuurformule van DET is: H₂N–CH₂–CH₂–NH–CH₂–CH₂–NH₂. Afhankelijk van de gekozen molverhouding tussen het dizuur en DET worden verschillende producten gevormd.$$, 'inline'),
  ('18f423c7-824f-4d51-8229-c851bdca45f9', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$reactie met ureum (stap 3)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context4.png$$,
   $$Stap 3: om nog meer waterstofbrugvormende groepen aan te brengen laat men de in stap 2 gevormde producten reageren met ureum. Atoomgroepen van de eenheden DET vormen atoombindingen met ureum-moleculen, waarbij onder andere atoomgroepen worden gevormd zoals hieronder weergegeven: een keten ~N(H)–CH₂–CH₂–N(H)–CH₂–CH₂–N(H)~ met aan het middelste stikstofatoom een C(=O)NH₂-groep gebonden. In deze reactie wordt nog een andere stof gevormd.$$, 'inline'),
  ('98b29949-2590-4b1d-a615-ba3c134d0a3a', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$hersteltijd van het materiaal bij verschillende temperaturen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context5.png$$,
   $$Als een stukje van dit materiaal wordt doorgesneden, worden de waterstofbruggen tussen de moleculen aan weerszijden van de snede verbroken. Door de beide zijden tegen elkaar te drukken, komen de waterstofbrugvormende groepen weer met elkaar in contact en worden weer waterstofbruggen gevormd. De mate waarin het materiaal eenvoudig hersteld kan worden, hangt onder andere sterk af van de temperatuur. Bij 23 °C kan nog volledig herstel worden verkregen tot een week na de breuk, bij 40 °C tot 48 uur en bij 90 °C tot 15 minuten.$$, 'inline'),
  ('145c0091-7565-4ffd-acff-41fa3897629c', 'f152d7a7-038d-4c18-92ac-8076160ea0ef', $$beperking tot droge omstandigheden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-zelfherstellend-rubber-context6.png$$,
   $$De toepassing van dit materiaal is beperkt tot droge omstandigheden. Als het materiaal onder vochtige omstandigheden beschadigd raakt, is het niet meer mogelijk een breuk te herstellen.$$, 'inline'),
  ('0877b8b3-872c-4da3-9c38-fb5178aef572', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$inleiding — vorming van epoxyhars uit amine en di-epoxide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context1.png$$,
   $$Carbon is een composiet samengesteld uit een netwerkpolymeer en koolstofvezels. Het netwerkpolymeer in carbon is een epoxyhars. De epoxyhars wordt gevormd uit twee monomeren: een amine en een zogeheten di-epoxide. Moleculen van het di-epoxide bevatten aan beide uiteinden een epoxidegroep: H₂C(–O–)CH–R–CH(–O–)CH₂ (di-epoxide). Wanneer het di-epoxide wordt gemengd met de amine treedt de volgende reactie op: R₁–NH₂ reageert met H₂C(–O–)CH–R₂ tot R₁–NH–CH₂–CH(OH)–R₂. Met R₁ en R₂ worden de overige delen van de moleculen aangeduid. De amine treedt hierbij op als een nucleofiel deeltje. Op de uitwerkbijlage bij deze opgave is de reactie onvolledig weergegeven in twee stappen. In stap 2 verplaatst zich een H atoom.$$, 'inline'),
  ('513d1c95-c144-426a-8a33-4f10cdc2813c', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$uitwerkbijlage vraag 15 — reactiestappen amine + epoxidegroep$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context2.png$$,
   $$Op de uitwerkbijlage staan de twee stappen van de reactie tussen de amine en de epoxidegroep onvolledig weergegeven. Stap 1: R₁–NH₂ (met de twee niet-bindende H-atomen aan het stikstofatoom) reageert met de epoxidegroep H₂C(–O–)CH–R₂ tot het tussenproduct R₁–N(H)–CH₂–CH(–O–)–R₂, waarbij de zuurstof nog in de ringvorm staat. Stap 2: dit tussenproduct reageert verder tot het eindproduct R₁–N–CH₂–CH(OH)–R₂, waarbij een H-atoom zich verplaatst van het stikstofatoom naar het zuurstofatoom. Beide stappen moeten op de uitwerkbijlage worden aangevuld met de ontbrekende elektronenparen, atomen, verplaatsingspijlen en formele ladingen.$$, 'uitwerkbijlage'),
  ('15903fa9-4fc6-4fff-99b3-46d0748d4018', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$epoxidegroep als cyclische ether — reactiviteit$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context3.png$$,
   $$Een epoxidegroep is op te vatten als een cyclische ethergroep. Van alle ethers blijken de stoffen met een epoxidegroep in de moleculen veel reactiever te zijn dan de lineaire ethers. De reden hiervoor is dat de bindingshoeken in de ring van een epoxidegroep afwijken van wat de VSEPR-theorie voorspelt. Hierdoor is de activeringsenergie voor het verbreken van de C–O binding in een epoxidegroep veel lager dan bij een lineaire ether.$$, 'inline'),
  ('8b916b60-4047-41e8-a89f-8a6fd210941d', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$definities EEM en AHEM; structuurformule DET$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context4.png$$,
   $$Men streeft ernaar dat in het materiaal geen reactieve groepen meer over zijn. Daarom moeten de ~NH groepen en de epoxidegroepen in een molverhouding 1:1 gemengd worden. Voor de gebruiker vermelden fabrikanten daarom twee waardes op de verpakking: de EEM en de AHEM. Deze waardes zijn als volgt gedefinieerd: EEM: het aantal gram van het di-epoxide per mol epoxidegroepen; AHEM: het aantal gram van de amine per mol aan stikstof gebonden waterstofatomen. De structuur van de veelgebruikte diëthyleentriamine (DET) is: H₂N–CH₂–CH₂–NH–CH₂–CH₂–NH₂.$$, 'inline'),
  ('a3811527-e879-431b-b699-1e74d040db04', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$EEM en AHEM van een specifieke bereiding$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context5.png$$,
   $$Bij een bereiding van epoxyhars wordt een di-epoxide gebruikt met een EEM van 189 gram en een amine met een AHEM van 15 gram.$$, 'inline'),
  ('2fca6fb9-0cb2-4bcf-9627-90507d8e590f', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$crosslinks en structuur van het di-epoxide (n tussen 0 en 25)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context6.png$$,
   $$Omdat de amine-moleculen meerdere reactieve plaatsen hebben, vormen deze crosslinks tussen de moleculen van het di-epoxide. De structuur van het meest gebruikte di-epoxide voor carbon bestaat uit een epoxidegroep aan beide uiteinden van een keten met n herhalende eenheden van het type –O–C₆H₄–C(CH₃)₂–C₆H₄–O–CH₂–CH(OH)–CH₂– tussen twee eindstandige epoxidegroepen. De waarde van n in dit monomeer kan liggen tussen 0 en 25. De waarde van n heeft onder meer invloed op de vervormbaarheid van de gevormde epoxyhars.$$, 'inline'),
  ('245e1fba-a654-49ba-88d3-c2f652848ebd', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$voorbehandeling van koolstofvezels met een oxidator en figuur 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context7.png$$,
   $$Om een voorwerp van carbon te produceren worden de twee monomeren samen met de koolstofvezels in een mal geperst. Voor de sterkte van het gevormde carbon is van belang dat de koolstofvezels goed hechten aan de epoxyhars. Op microniveau bestaan de vezels uit meerdere koolstoflaagjes van elk één atoom dik, vergelijkbaar met grafiet (zie Binas-tabel 67E). Dankzij de platte vorm liggen de lagen dicht op elkaar. Om de hechting met het netwerkpolymeer te verbeteren worden de koolstofvezels voorbehandeld met een oxidator. Figuur 1 toont hoe een laagje er dan uit kan zien: een grafietlaagje waarin verspreid zuurstofhoudende groepen zijn ingebouwd, zoals carbonzuurgroepen (–COOH), hydroxylgroepen (–OH) en brugzuurstofatomen tussen naburige koolstofatomen.$$, 'inline'),
  ('103a0d0a-4a6f-4918-9794-14b7e1afdeab', '5ebab028-65b7-4d56-bfd0-a9edcef71d21', $$afname van de sterkte van de koolstofvezels door voorbehandeling$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-carbon-context8.png$$,
   $$Door deze voorbehandeling blijkt de sterkte van de koolstofvezels zelf af te nemen. Men verklaart dit uit een afname van de onderlinge hechting van de koolstoflaagjes.$$, 'inline'),
  ('f8146c12-6aa5-4c9f-a3da-8cde8b71a756', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$productie van waterstof uit methaan — figuur 1 (gas-shiftreactoren) en evenwicht$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context1.png$$,
   $$Ammoniak wordt in Europa vooral geproduceerd uit stikstof en methaan. Methaan treedt in het proces op als energiebron maar ook als bron van waterstofatomen. Om waterstof te produceren uit methaan wordt bij hoge temperatuur en druk methaan in reactie gebracht met water en zuurstof. Hierbij wordt een gasmengsel van CO, H₂O en H₂ verkregen. Om een groot deel van het aanwezige CO te verwijderen, wordt vervolgens in twee reactoren de zogeheten gas-shift reactie uitgevoerd. Figuur 1 toont hoe dit deel van het proces wordt uitgevoerd: de gasstroom H₂/CO/H₂O gaat eerst door reactor R1 (430 °C), wordt vervolgens gekoeld en gaat daarna door reactor R2 (240 °C), waarna de gasstroom H₂/CO/H₂O/CO₂ de installatie verlaat. Zowel in R1 als in R2 is een katalysator aanwezig en heerst een hoge druk. In beide reactoren treedt onderstaand evenwicht op: CO + H₂O ⇌ CO₂ + H₂. In de gasstroom na R1 bedraagt het volumepercentage CO nog 2-4% en na R2 is er nog 1% CO.$$, 'inline'),
  ('59286a12-f1ef-46d3-84ed-c9231a87f872', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$afscheiding van water en CO2 uit de gasstroom na R2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context2.png$$,
   $$De waterstof afkomstig uit R2 wordt in een aantal stappen afgescheiden van de rest van het gasmengsel. Allereerst wordt water afgescheiden. Daarna wordt CO₂ gescheiden van de overige gassen.$$, 'inline'),
  ('483e16b5-4a8f-415e-9af9-c1182da3120d', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$totaalreactie van de ammoniakproductie (reactie 1)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context3.png$$,
   $$De gezuiverde waterstof wordt in een volgende reactor in reactie gebracht met stikstof. Het totaalproces van de productie van ammoniak uit onder andere methaan kan worden weergegeven met onderstaande reactievergelijking (reactie 1): 0,40 CH₄ + 0,050 O₂ + 0,70 H₂O + 0,50 N₂ → 0,40 CO₂ + 1,0 NH₃. Als in een proces deze molverhoudingen worden toegepast, is het proces ongeveer energieneutraal. Dat betekent dat vrijwel geen extra energie nodig is of overtollige warmte ontstaat.$$, 'inline'),
  ('de4c23ad-a884-462b-a05f-13787cb1a06b', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$extra energiebehoefte in de praktijk (25% meer methaan)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context4.png$$,
   $$In de praktijk blijkt dat de meest efficiënte ammoniakfabrieken 25% meer energie nodig hebben dan wat op basis van reactie 1 kan worden berekend. In het proces wordt dan ook 25% meer methaan per mol ammoniak gebruikt. De extra hoeveelheid methaan levert dan de benodigde energie.$$, 'inline'),
  ('76484827-bcad-48f0-911d-ba10f0ff6087', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$relatief energieverbruik voor waterstofproductie uit verschillende grondstoffen (tabel 1)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context5.png$$,
   $$De waterstof die nodig is voor de productie van ammoniak kan ook worden verkregen uit andere processen. Tabel 1 toont het relatieve energieverbruik voor de productie van waterstof uit een aantal grondstoffen. In de reacties zijn de grondstoffen zware stookolie en nafta weergegeven met de gemiddelde verhouding tussen het aantal C atomen en het aantal H atomen in deze grondstoffen. Tabel 1 — grondstof (proces): reactie, relatief energieverbruik: kolen: C + 2 H₂O → 2 H₂ + CO₂, 170%; zware stookolie: CH + 2 H₂O → 2½ H₂ + CO₂, 135%; nafta: CH₂ + 2 H₂O → 3 H₂ + CO₂, 104%; aardgas: CH₄ + 2 H₂O → 4 H₂ + CO₂, 100%.$$, 'inline'),
  ('4ba035b4-afd7-4255-b76e-3af8ba8470e4', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$afweging tussen zware stookolie en nafta$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context6.png$$,
   $$Zware stookolie en nafta zijn producten afkomstig van de destillatie van aardolie. Als onvoldoende aardgas beschikbaar is, kan aan de hand van tabel 1 een afweging worden gemaakt tussen de grondstoffen zware stookolie en nafta.$$, 'inline'),
  ('8fac8afa-a88c-40bf-b554-327bb2651106', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$productie van waterstof uit houtafval$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context7.png$$,
   $$Onderzocht is of het mogelijk is om gedroogd houtafval als duurzaam alternatief voor methaan te gebruiken voor de productie van ammoniak. In het onderzoek leverde 2,7 kg houtafval voldoende waterstof voor de productie van 1,0 kg ammoniak. De omzetting van alle koolstof uit het houtafval leidt uiteindelijk tot een CO₂-uitstoot van 3,3 kg CO₂ per kg ammoniak.$$, 'inline'),
  ('bac790d1-4c6c-46d2-829d-66b71f34be17', 'eb113505-43ac-4732-90bc-d9cc2b74dec6', $$gemodelleerde CO2-uitstoot: aardgas versus houtafval$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2016-ii-duurzame-ammoniak-context8.png$$,
   $$In het onderzoek is met behulp van modellen berekend dat de CO₂-uitstoot bij de productie van ammoniak uit aardgas 1,9 kg CO₂ per kg ammoniak bedraagt. De productie van ammoniak uit houtafval levert een CO₂-uitstoot van 4,1 kg CO₂ per kg ammoniak. In de modellen is ook de CO₂-uitstoot die optreedt buiten de ammoniakfabriek opgenomen. Op basis van de gemodelleerde CO₂-uitstoot van beide processen kan worden berekend dat houtafval een lagere bijdrage levert aan het versterkte broeikaseffect dan aardgas.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('953bd834-6856-4aec-8bd8-f6674fd6afb3', '80c5b769-0dba-40cd-8340-638f2057435f', 1,
   '[{"domain": "Chemie van het leven", "subdomain": "Structuur en functie"}, {"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["aminozuur", "peptidebinding", "structuurformule", "waterstofbrug", "eiwit", "cysteïne"]'::jsonb,
   $$Structuurformule van het peptidefragment ~T-C-T~ tekenen en de waterstofbrugbinding met een watermolecuul aangeven$$,
