  ('6dc3f2f8-16c0-4513-80b2-f0bb0b7d15eb', 'f326ff31-8bdb-4988-bae3-7d34a855b82e', 7,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["Nafion", "polymeer", "molecuulformule", "sulfonzuurgroep", "polymerisatiegraad"]'::jsonb,
